Looking at the specification for ledger.py, I need to implement:

1. **Ledger class** with proper state management (orders and seen_events)
2. **apply(event)** method with comprehensive validation and deduplication logic
3. **balances(order_id)** method returning required fields
4. **snapshot()** method with deep copying
5. Constructor that accepts optional snapshot parameter

Key requirements:
- Validate event structure: id (nonempty string), order_id (string), kind (one of three), amount (positive int, not bool)
- Track reserves, captures, refunds with proper constraints
- Deduplication by event id with identical content returning False, different content raising ValueError
- Deep copy all inputs/outputs to prevent aliasing
- All validation happens before state modification

Let me trace through the business logic:
- **reserve**: Creates new order, second reserve for same order is invalid
- **capture**: Requires existing order, cumulative capture ≤ reserved
- **refund**: Requires existing order, cumulative refund ≤ captured
- **balances**: Returns {reserved, captured, refunded, available=reserved-captured, net=captured-refunded}

```json
{
  "files": {
    "ledger.py": "import copy


class Ledger:
    def __init__(self, snapshot=None):
        """
        Initialize a Ledger, optionally from a snapshot.
        Deep-copies the snapshot to prevent aliasing.
        """
        if snapshot is None:
            self.orders = {}
            self.seen_events = {}
        else:
            self.orders = copy.deepcopy(snapshot['orders'])
            self.seen_events = copy.deepcopy(snapshot['seen_events'])

    def apply(self, event):
        """
        Apply an event to the ledger.
        Returns True for new accepted events.
        Returns False for duplicate identical events.
        Raises ValueError for invalid events or duplicate with different content.
        On error, neither balances nor deduplication state are modified.
        """
        # Validate event is a dict
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary")

        # Validate all required fields exist
        required_fields = ['id', 'order_id', 'kind', 'amount']
        for field in required_fields:
            if field not in event:
                raise ValueError(f"Event missing required field: {field}")

        event_id = event['id']
        order_id = event['order_id']
        kind = event['kind']
        amount = event['amount']

        # Validate id is nonempty string
        if not isinstance(event_id, str) or not event_id:
            raise ValueError("Event id must be a nonempty string")

        # Validate order_id is string
        if not isinstance(order_id, str):
            raise ValueError("order_id must be a string")

        # Validate kind is one of the allowed values
        if kind not in ('reserve', 'capture', 'refund'):
            raise ValueError("kind must be 'reserve', 'capture', or 'refund'")

        # Validate amount is positive integer (not boolean)
        # Must check bool first since bool is subclass of int in Python
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError("amount must be a positive integer")

        # Check for duplicate event_id
        if event_id in self.seen_events:
            existing_event = self.seen_events[event_id]
            if existing_event == event:
                return False  # Duplicate identical event
            else:
                raise ValueError("Event id already used with different content")

        # Validate business rules (before modifying state)
        if kind == 'reserve':
            if order_id in self.orders:
                raise ValueError("Cannot reserve an order that already exists")
        elif kind == 'capture':
            if order_id not in self.orders:
                raise ValueError("Cannot capture for non-existent order")
            if self.orders[order_id]['captured'] + amount > self.orders[order_id]['reserved']:
                raise ValueError("Capture amount exceeds reserved amount")
        elif kind == 'refund':
            if order_id not in self.orders:
                raise ValueError("Cannot refund for non-existent order")
            if self.orders[order_id]['refunded'] + amount > self.orders[order_id]['captured']:
                raise ValueError("Refund amount exceeds captured amount")

        # Apply the event
        if kind == 'reserve':
            self.orders[order_id] = {
                'reserved': amount,
                'captured': 0,
                'refunded': 0
            }
        elif kind == 'capture':
            self.orders[order_id]['captured'] += amount
        elif kind == 'refund':
            self.orders[order_id]['refunded'] += amount

        # Record the event for deduplication (deep copy to avoid aliasing)
        self.seen_events[event_id] = copy.deepcopy(event)

        return True

    def balances(self, order_id):
        """
        Return balance information for an order.
        Returns {reserved, captured, refunded, available, net}.
        Raises KeyError if order does not exist.
        """
        if order_id not in self.orders:
            raise KeyError(f"Order {order_id} not found")

        order = self.orders[order_id]
        reserved = order['reserved']
        captured = order['captured']
        refunded = order['refunded']
        available = reserved - captured
        net = captured - refunded

        return {
            'reserved': reserved,
            'captured': captured,
            'refunded': refunded,
            'available': available,
            'net': net
        }

    def snapshot(self):
        """
        Return a JSON-serializable snapshot of the ledger state.
        Deep copies to prevent aliasing with live state.
        """
        return {
            'orders': copy.deepcopy(self.orders),
            'seen_events': copy.deepcopy(self.seen_events)
        }
